import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Map<String, Integer> soni = new LinkedHashMap<>();
        for (int i = 0; i < n; i++) {
            in.next();
            String tuz = in.next();
            soni.put(tuz, soni.getOrDefault(tuz, 0) + 1);
        }
        boolean bor = false;
        for (Map.Entry<String, Integer> e : soni.entrySet()) {
            if (e.getValue() >= 1) {
                System.out.println(e.getKey() + " " + e.getValue());
                bor = true;
            }
        }
        if (!bor) {
            System.out.println("ok");
        }
    }
}

starter.cpp:
#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<string> tartib;
    map<string, int> soni;
    for (int i = 0; i < n; i++) {
        string login, tuz;
        cin >> login >> tuz;
        if (soni[tuz] == 0) {
            tartib.push_back(tuz);
        }
        soni[tuz]++;
    }
    bool bor = false;
    for (const string& t : tartib) {
        if (soni[t] >= 1) {
            cout << t << " " << soni[t] << endl;
            bor = true;
        }
    }
    if (!bor) {
        cout << "ok" << endl;
    }
    return 0;
}

